    return ss,mfe

def random_seq():
    # unpaired A-biased, paired complementary G-C/C-G random
    seq=['A']*len(T)
    # assign pairs
    done=set()
    for i in range(len(T)):
        if i in done: continue
        if i in pairs:
            j=pairs[i]
