    for _ in range(n):
        i=random.randrange(len(T))
        l[i]=random.choice('ACGU')
    return ''.join(l)

def targeted_mutate(seq, ss):
    # find spurious pairs and missing pairs
    spurious=[]; missing=[]
    # parse ss pairs
    sspairs={}
    st2=[]
    for i,c in enumerate(ss):
        if c=='(':st2.append(i)
