            j=st2.pop();sspairs[j]=i;sspairs[i]=j
    for i in range(len(T)):
        if i<pairs.get(i,9999):
            j=pairs[i]
            if j!=sspairs.get(i):
                missing.append((i,j))
    for i in range(len(ss)):
        if i<sspairs.get(i,9999):
            j=sspairs[i]
            if j!=pairs.get(i):
                spurious.append((i,j))
    l=list(seq)
    # break spurious: ensure mismatch
    for i,j in spurious:
