    # strengthen missing
    for i,j in missing:
        r=random.choice(['GC','CG'])
        l[i]=r[0];l[j]=r[1]
    # also some random noise
    if random.random()<0.3:
        for _ in range(random.randint(1,3)):
            k=random.randrange(len(T))
            l[k]=random.choice('ACGU')
    return ''.join(l)

def anneal(seed, steps=4000):
    random.seed(seed)
    seq=random_seq()
    best,score_best = seq, score(seq)[0]
